# db.py: saves the app's data in database.db (SQLite). Students do NOT edit this file.
# Open database.db with the "SQLite Viewer" extension in VS Code to see your tables.
import os
import sqlite3

PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "database.db")


def run(sql, params=()):
    con = sqlite3.connect(PATH)
    try:
        cur = con.execute(sql, params)
        con.commit()
        return cur.lastrowid
    finally:
        con.close()


def rows(sql, params=()):
    con = sqlite3.connect(PATH)
    con.row_factory = sqlite3.Row
    try:
        return [dict(r) for r in con.execute(sql, params).fetchall()]
    finally:
        con.close()


def many(sqls):
    """Run several (sql, params) in one transaction."""
    con = sqlite3.connect(PATH)
    try:
        for sql, params in sqls:
            con.execute(sql, params)
        con.commit()
    finally:
        con.close()
